69	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
