266	    /** Matches a well-formed postcode: exactly 4 digits. */
267	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
268	
269	    /**
270	     * Region -> inclusive 4-digit postcode range {low, high}. A city's region is derived from the
271	     * fixed city-to-region table ({@link Owner#getRegion()}); a region absent from this map (i.e.
272	     * {@code UNKNOWN}) carries no range rule and accepts any 4-digit postcode.
273	     */
274	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
275	        "NSW", new int[] {2000, 2099},
276	        "VIC", new int[] {3000, 3099},
277	        "QLD", new int[] {4000, 4099});
278	
279	    /**
280	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
281	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
282	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
283	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode.
284	     */
285	    private static boolean isPostcodeValidForCity(Owner owner) {
286	        String postcode = owner.getPostcode();
287	        if (postcode == null) {
288	            return true;
289	        }
290	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
291	            return false;
292	        }
293	        int[] range = REGION_POSTCODE_RANGES.get(owner.getRegion());
294	        if (range == null) {
295	            return true;
296	        }
297	        int value = Integer.parseInt(postcode);
298	        return value >= range[0] && value <= range[1];
299	    }
300	
301	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
302	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
303	
304	    /**
305	     * Required national-number length per country code: '+61' (Australia) expects 9 national
306	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
307	     * national part is not the required length is rejected.
308	     */
309	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
310	        "+61", 9, "+1", 10);
311	
312	    /**
313	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
314	     * code are kept when present; otherwise country code '+61' is assumed and a single
315	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
316	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
317	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
318	     * Returns {@code null} when the number cannot form a valid E.164 value.
319	     */
320	    private static String normalizeTelephone(String telephone) {
321	        if (telephone == null) {
322	            return null;
323	        }
324	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
325	        String e164;
326	        if (cleaned.startsWith("+")) {
327	            e164 = cleaned;
328	        } else {
329	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
330	            e164 = "+61" + national;
331	        }
332	        if (!E164_PATTERN.matcher(e164).matches()) {
333	            return null;
334	        }
335	        return hasValidNationalNumberLength(e164) ? e164 : null;
336	    }
337	
338	    /**
339	     * Whether the national number of a well-formed E.164 value has the length required for its
340	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
341	     * per-country length rule and are accepted.
342	     */
343	    private static boolean hasValidNationalNumberLength(String e164) {
344	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
345	            String countryCode = entry.getKey();
346	            if (e164.startsWith(countryCode)) {
347	                return e164.length() - countryCode.length() == entry.getValue();
348	            }
349	        }
350	        return true;
351	    }
352	
353	    /**
354	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
355	     * code, membership number, household id, namesake count and household member count. Each is
356	     * derived from the owner's already-normalized fields and the existing owner population, so this
357	     * must run before the owner is saved, while the counts still exclude the owner being created.
358	     */
359	    private void assignRegistrationAttributes(Owner owner) {
360	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
361	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
362	        owner.setHouseholdId(householdId(owner));
363	        owner.setNamesakeCount(countNamesakes(owner));
364	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
365	    }
366	
367	    /**
368	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
369	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
370	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
371	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
372	     */
373	    private String generateCustomerCode(String city, String lastName) {
374	        String city3 = firstThreeLetters(city);
375	        String last3 = firstThreeLetters(lastName);
376	        int sequence = countOwnersInCity(city) + 1;
377	        return String.format("%s-%s-%04d", city3, last3, sequence);
378	    }
379	
380	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
381	    private static String firstThreeLetters(String value) {
382	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
383	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
384	    }
385	
386	    /**
387	     * The number of existing owners registered in {@code city}, compared case-insensitively
388	     * with collapsed whitespace.
389	     */
390	    private int countOwnersInCity(String city) {
391	        String normalized = normalizeHouseholdField(city);
392	        return (int) this.clinicService.findAllOwners().stream()
393	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
394	            .count();
395	    }
396	
397	    /**
398	     * The effective registration date to store for a new owner: the date supplied on the request
399	     * when present, otherwise the current server date, in either case rolled forward to a business
400	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
401	     * This single point of resolution is what every registration-date-derived value (the stored
402	     * date, the membership number's year segment, the per-day create-limit) is computed from.
403	     */
404	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
405	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
406	        return toBusinessDay(date);
407	    }
408	
409	    /**
410	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
411	     * following Monday; a weekday is returned unchanged.
412	     */
413	    private static LocalDate toBusinessDay(LocalDate date) {
414	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
415	            date = date.plusDays(1);
416	        }
417	        return date;
418	    }
419	
420	    /**
421	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
422	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
423	     */
424	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
425	        String yy = String.format("%02d", registrationDate.getYear() % 100);
426	        return customerCode + "-M" + yy;
427	    }
428	
429	    /**
430	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
431	     * last name, compared case-insensitively.
432	     */
433	    private int countNamesakes(Owner owner) {
434	        String firstName = normalizeHouseholdField(owner.getFirstName());
435	        String lastName = normalizeHouseholdField(owner.getLastName());
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
438	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
439	            .count();
440	    }
441	
442	    /**
443	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
444	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
445	     * unusually high daily signup volume.
446	     */
447	    private boolean isBulkSignupWarning() {
448	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
449	    }
450	
451	    /** The number of existing owners whose registration date is {@code date}. */
452	    private int countOwnersRegisteredOn(LocalDate date) {
453	        return (int) this.clinicService.findAllOwners().stream()
454	            .filter(existing -> date.equals(existing.getRegistrationDate()))
455	            .count();
456	    }
457	
458	    /**
459	     * The single derived key all duplicate detection flows through, formed from the owner's
460	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
461	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
462	     * id is derived, so the household segment is empty at that point. Because the telephone is part
463	     * of the key, two owners in the same household with different telephones resolve to different
464	     * keys and are both allowed.
465	     */
466	    private static String identityKey(Owner owner) {
467	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
468	        String email = owner.getEmail() == null ? "" : owner.getEmail();
469	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
470	        return telephone + "|" + email + "|" + household;
471	    }
472	
473	    /**
474	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
475	     * duplicate condition: the previously separate telephone, email and household checks are now all
476	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
477	     * trips it is rejected with {@code 409 CONFLICT}.
478	     */
479	    private boolean isDuplicate(Owner owner) {
480	        String key = owner.getIdentityKey();
481	        return this.clinicService.findAllOwners().stream()
482	            .map(Owner::getIdentityKey)
483	            .filter(existing -> existing != null)
484	            .anyMatch(key::equals);
485	    }
486	
487	    /** Common street-type abbreviations expanded during address normalization. */
488	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
489	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
490	
491	    /**
492	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
493	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
494	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
495	     * string when {@code address} is null or blank after normalization.
496	     */
497	    private static String normalizeAddress(String address) {
498	        if (address == null) {
499	            return "";
500	        }
501	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
502	        if (collapsed.isEmpty()) {
503	            return "";
504	        }
505	        StringBuilder sb = new StringBuilder(collapsed.length());
506	        for (String token : collapsed.split(" ")) {
507	            if (sb.length() > 0) {
508	                sb.append(' ');
509	            }
510	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
511	        }
512	        return sb.toString();
513	    }
514	
515	    /**
516	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
517	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
518	     */
519	    private static String normalizeHouseholdField(String value) {
520	        if (value == null) {
521	            return "";
522	        }
523	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
524	    }
525	
526	    /**
527	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
528	     * same address compared case-insensitively with collapsed whitespace.
529	     */
530	    private List<Owner> findHousemates(Owner owner) {
531	        String lastName = normalizeHouseholdField(owner.getLastName());
532	        String address = normalizeHouseholdField(owner.getAddress());
533	        return this.clinicService.findAllOwners().stream()
534	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
535	                && normalizeHouseholdField(existing.getAddress()).equals(address))
536	            .toList();
537	    }
