18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("errors", List.<String>of());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingResult bindingResult = e.getBindingResult();
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
139	        if (bindingResult.hasErrors()) {
140	            List<FieldError> fieldErrors = bindingResult.getFieldErrors();
141	            detail.setProperty("errors", fieldErrors.stream()
142	                .map(FieldError::getField)
143	                .distinct()
144	                .toList());
145	            detail.setProperty("schemaValidationErrors", fieldErrors.stream()
146	                .map(this::toValidationMessage)
147	                .toList());
148	            logger.debug("Validation error at {} {}: {}",
149	                request.getMethod(),
150	                request.getRequestURI(),
151	                fieldErrors);
152	        }
153	        return ResponseEntity.status(status).body(detail);
154	    }
155	
156	    /**
157	     * Describes a single {@link FieldError} both as a human-readable message and as the structured
158	     * properties consumed by API clients.
159	     *
160	     * @param fieldError the rejected field reported by Bean Validation
161	     * @return the {@link ValidationMessageDto} for that field
162	     */
163	    private ValidationMessageDto toValidationMessage(FieldError fieldError) {
164	        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
165	        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
166	        String message = "Field '%s' %s (rejected value: %s)".formatted(
167	            fieldError.getField(),
168	            defaultMessage,
169	            rejectedValue);
170	        return new ValidationMessageDto(message)
171	            .putAdditionalProperty("field", fieldError.getField())
172	            .putAdditionalProperty("rejectedValue", rejectedValue)
173	            .putAdditionalProperty("defaultMessage", defaultMessage);
174	    }
175	
176	}
