        owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
    OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
    ownerDto.setBulkSignupWarning(isBulkSignupWarning());
    headers.setLocation(UriComponentsBuilder.newInstance()
        .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
    return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
}
```

Security: method-level `@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")` (line 117) runs before the method body; on failure Spring Security throws `AccessDeniedException`.

Note the controller body itself is NOT annotated `@Transactional` (unlike `deleteOwner`), so there is no controller-level transaction — each `clinicService` call has its own transaction (see section 3/6).

